package com.pulsefit.subscription;
import javax.crypto.spec.SecretKeySpec; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.oauth2.jwt.*; import org.springframework.security.web.SecurityFilterChain;
@Configuration public class SecurityConfig { @Bean SecurityFilterChain security(HttpSecurity h)throws Exception{return h.csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/actuator/health","/internal/subscriptions/**").permitAll().anyRequest().authenticated()).oauth2ResourceServer(o->o.jwt(j->{})).build();} @Bean JwtDecoder jwtDecoder(){return NimbusJwtDecoder.withSecretKey(new SecretKeySpec("PulseFit-PS023-JWT-Secret-Key-2026-ChangeMe-32Bytes".getBytes(),"HmacSHA256")).build();} }
